def crc64(data):
    crc = 0
    poly = 0x95AC9329AC4BC9B5
    for b in data:
        crc ^= b
        for _ in range(8):
            crc = (crc >> 1) ^ poly if crc & 1 else crc >> 1
    return crc

def downgrade(p, ver):
    body = bytearray(p[:-8])          # includes original version bytes at [-10:-8]
    body[-2] = ver                    # version low byte
    body[-1] = 0
    body += crc64(bytes(body)).to_bytes(8, 'little')
