    for k in keys:
        si = r.execute_command('XINFO','STREAM',k)
        sd = dict(zip(si[0::2], si[1::2]))
        idmp = {x: sd.get(x) for x in (b'pids-tracked',b'iids-tracked',b'iids-added',b'iids-duplicates',b'idmp-duration',b'idmp-maxsize')}
        gs = r.execute_command('XINFO','GROUPS',k)
        ginfo=[]
        for g in gs:
            gd = dict(zip(g[0::2], g[1::2]))
            cs = r.execute_command('XINFO','CONSUMERS',k,gd[b'name'])
            cinfo=[]
            for c in cs:
                cd = dict(zip(c[0::2], c[1::2])); cinfo.append(cd)
            sum_pending = sum(c[b'pending'] for c in cinfo)
            ginfo.append((gd[b'name'], gd[b'pending'], gd[b'last-delivered-id'], gd.get(b'entries-read'), gd.get(b'lag'), sum_pending, [(c[b'name'],c[b'pending'],c[b'idle'],c[b'inactive']) for c in cinfo]))
        report.append((k, sd[b'length'], sd[b'last-generated-id'], sd[b'max-deleted-entry-id'], sd[b'entries-added'], sd[b'recorded-first-entry-id'], idmp, ginfo))
    if cur==0: break
unowned = 0; idmp_nz = 0
for k,ln,lg,md,ea,rf,idmp,gi in report:
    if any(v not in (0,None) for kk,v in idmp.items() if kk != b'idmp-duration' and kk != b'idmp-maxsize') : idmp_nz += 1; print('IDMP NONZERO', k, idmp)
    for name,pel,lid,er,lag,sump,cons in gi:
        if sump != pel: unowned += 1; print('UNOWNED', k, name, pel, sump)
    print(k.decode(), 'len',ln,'last',lg,'maxdel',md,'added',ea,'first-rec',rf,'groups',len(gi), {kk:idmp[kk] for kk in (b'idmp-duration',b'idmp-maxsize')})
    for name,pel,lid,er,lag,sump,cons in gi:
        print('   grp',name,'pel',pel,'last',lid,'read',er,'lag',lag,'cons',cons)
print('total streams', len(report), 'unowned-nack groups', unowned, 'idmp-nonzero', idmp_nz)
